import * as THREE from 'three/webgpu';
import { texture, uv, vec2, vec4, float, uniform } from 'three/tsl';

export default function createNode(config, ctx) {
  const width = 1.6;
  const height = 1.0;

  const geometry = new THREE.PlaneGeometry(width, height);
  const material = new THREE.MeshBasicNodeMaterial({ transparent: true });

  const imageUrl = config.assets?.imageUrl || '/prism-mock/home/nodes/cta-hero-isolated.png';
  const map = ctx.textureLoader.load(imageUrl);
  map.colorSpace = THREE.SRGBColorSpace;

  const grainAmount = uniform(0.03);

  const uvNode = uv();
  const baseColor = texture(map, uvNode);

  // subtle static grain via hashed noise from uv (no time dependency -> static composition)
  const hashInput = uvNode.mul(vec2(512.0, 320.0));
  const noise = hashInput.x.mul(12.9898).add(hashInput.y.mul(78.233)).sin().mul(43758.5453).fract();
  const grain = noise.sub(0.5).mul(grainAmount);

  const finalColor = vec4(
    baseColor.rgb.add(vec2(grain, grain).x),
    baseColor.a
  );

  material.colorNode = finalColor;

  const mesh = new THREE.Mesh(geometry, material);
  mesh.name = 'hub-collection-card-1-plane';

  const pos = config.scenePlacement?.position || { x: -3.2, y: -0.3, z: 0 };
  const rot = config.scenePlacement?.rotation || { x: 0, y: 0, z: 0 };
  const scl = config.scenePlacement?.scale || { x: 1, y: 1, z: 1 };

  mesh.position.set(pos.x, pos.y, pos.z);
  mesh.rotation.set(rot.x, rot.y, rot.z);
  mesh.scale.set(scl.x, scl.y, scl.z);

  mesh.userData.handlers = {};

  mesh.userData.cleanup = () => {
    geometry.dispose();
    material.dispose();
    if (map) map.dispose();
  };

  return mesh;
}
